// ─── TABLE: Improvement ranking ───────────────────────────────────────────────
(function buildTable() {
  const rows = countries.map(c => {
    const start = mmrData[c][0];
    const end   = mmrData[c][4];
    const abs   = start - end;
    const pct   = Math.round((abs / start) * 100);
    return { country: c, start, end, abs, pct };
  }).sort((a,b) => b.abs - a.abs);

  const maxAbs = rows[0].abs;
  const tbody = document.getElementById('improvementBody');

  rows.forEach(r => {
    const pace = r.pct >= 60 ? 'fast' : r.pct >= 30 ? 'slow' : 'bad';
    const paceLabel = r.pct >= 60 ? 'Strong' : r.pct >= 30 ? 'Moderate' : 'Slow';
    const barW = Math.round((r.abs / maxAbs) * 120);
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td><span class="country-name">${r.country}</span></td>
      <td style="font-family:var(--font-mono)">${r.start}</td>
      <td style="font-family:var(--font-mono)">${r.end}</td>
      <td>
        <span class="bar-spark" style="width:${barW}px;background:${palette[r.country]}88"></span>
        <span style="font-family:var(--font-mono)">${r.abs}</span>
      </td>
      <td><span class="pct-badge ${pace}">${r.pct}%</span></td>
      <td style="color:var(--text-dim);font-size:13px">${paceLabel}</td>
    `;
    tbody.appendChild(tr);
  });
})();

